#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>
#include <cute/tensor.hpp>

using namespace cute;

#define TILE_H 32
#define TILE_W 32
#define BLOCK_H 16
#define BLOCK_W 16
__global__ void conv2d_kernel(
    const cute::bfloat16_t* __restrict__ in_ptr,
    const cute::bfloat16_t* __restrict__ w_ptr,
    cute::bfloat16_t* __restrict__ out_ptr,
    int N, int C, int H, int W,
    int OC, int KH, int KW,
    int OH, int OW)
{
    // Global tensors described with CuTe layouts
    Tensor gIn = make_tensor(make_gmem_ptr(in_ptr),
                              make_shape(N, C, H, W),
                              make_stride(C * H * W, H * W, W, 1));
    Tensor gOut = make_tensor(make_gmem_ptr(out_ptr),
                               make_shape(N, OC, OH, OW),
                               make_stride(OC * OH * OW, OH * OW, OW, 1));
    int n = blockIdx.z;
    int tile_row = blockIdx.y * TILE_H;
    int tile_col = blockIdx.x * TILE_W;
    int tx = threadIdx.x; // 0..BLOCK_W-1
    int ty = threadIdx.y; // 0..BLOCK_H-1
    extern __shared__ unsigned char smem_raw[];
    cute::bfloat16_t* s_in = reinterpret_cast<cute::bfloat16_t*>(smem_raw);
    const int in_tile_h = TILE_H + KH - 1;
    const int in_tile_w = TILE_W + KW - 1;
    cute::bfloat16_t* s_w = s_in + C * in_tile_h * in_tile_w;
    // Shared memory tensors via CuTe (mixed static/dynamic layouts)
    Tensor sIn = make_tensor(make_smem_ptr(s_in),
                              make_shape(C, in_tile_h, in_tile_w),
                              make_stride(in_tile_h * in_tile_w, in_tile_w, 1));
    Tensor sW = make_tensor(make_smem_ptr(s_w),
                             make_shape(OC, C, KH, KW),
                             make_stride(C * KH * KW, KH * KW, KW, 1));
    int tid = ty * BLOCK_W + tx;
    int nthreads = BLOCK_H * BLOCK_W;
    // Cooperative load of weights into shared memory
    int wsize = OC * C * KH * KW;
    for (int i = tid; i < wsize; i += nthreads) {
        s_w[i] = w_ptr[i];
    }
    // Cooperative load of input tile (with halo) into shared memory
    int in_tile_size = C * in_tile_h * in_tile_w;
    for (int i = tid; i < in_tile_size; i += nthreads) {
        int c = i / (in_tile_h * in_tile_w);
        int rem = i % (in_tile_h * in_tile_w);
        int r = rem / in_tile_w;
        int cc = rem % in_tile_w;
        int gh = tile_row + r;
        int gw = tile_col + cc;
        cute::bfloat16_t val = cute::bfloat16_t(0.0f);
        if (gh < H && gw < W) {
            val = gIn(n, c, gh, gw);
        }
        sIn(c, r, cc) = val;
    }
    __syncthreads();
    // Register-blocked output computation: each thread computes a 2x2
    // block of outputs within the 32x32 output tile, improving reuse of
    // shared-memory operands (sIn/sW) per thread and amortizing loop
    // overhead across multiple accumulators held in registers.
    #pragma unroll
    for (int rh = 0; rh < 2; ++rh) {
        #pragma unroll
        for (int rw = 0; rw < 2; ++rw) {
            int local_h = ty + rh * BLOCK_H;
            int local_w = tx + rw * BLOCK_W;
            int oh = tile_row + local_h;
            int ow = tile_col + local_w;
            if (oh < OH && ow < OW) {
                for (int oc = 0; oc < OC; ++oc) {
                    float acc = 0.0f;
                    for (int c = 0; c < C; ++c) {
                        for (int kh = 0; kh < KH; ++kh) {
                            for (int kw = 0; kw < KW; ++kw) {
                                float a = float(sIn(c, local_h + kh, local_w + kw));
                                float b = float(sW(oc, c, kh, kw));
                                acc += a * b;
                            }
                        }
                    }
                    gOut(n, oc, oh, ow) = cute::bfloat16_t(acc);
                }
            }
        }
    }
